def default_state(customer_id: str, profile: dict, accounts: list) -> dict:
    return {'customer_id': customer_id, 'profile': profile, 'accounts': accounts, 'transaction': {'baseline_income': 0.0, 'income_credits': [], 'recent_income': 0.0, 'income_change_pct': 0.0, 'healthcare_spend': 0.0, 'baby_spend': 0.0, 'large_outbound_transfers': [], 'savings_drawdown': 0.0, 'standing_instructions_cancelled': False, 'card_purchase_count_recent': 0, 'anomaly_flags': [], 'last_updated': None}, 'usage': {'baseline_logins_per_week': 0.0, 'logins_live': [], 'recent_logins_per_week': 0.0, 'login_change_pct': 0.0, 'login_trend': 'stable', 'recent_searches': [], 'feature_flags': [], 'anomaly_flags': [], 'last_updated': None}, 'support': {'open_tickets': 0, 'resolved_tickets': 0, 'ticket_history': [], 'last_sentiment': 0.0, 'last_intent': None, 'last_category': None, 'anomaly_flags': [], 'last_updated': None}, 'kyc': {'dependents_changed': False, 'dependents_old': None, 'dependents_new': None, 'anomaly_flags': [], 'last_updated': None}, 'inferred_state': 'no_significant_event', 'confidence_band': 'low', 'reasoning': [], 'recommended_action': 'no_action', 'action_subtype': None, 'hitl_status': 'auto_approved', 'agent_findings': [], 'events_processed': 0, 'current_time': None, 'last_updated': None}

def add_finding(state: dict, agent: str, finding: str, value, confidence: float, evidence: list):
    state['agent_findings'] = [f for f in state['agent_findings'] if not (f['agent'] == agent and f['finding'] == finding)]
    state['agent_findings'].append({'agent': agent, 'finding': finding, 'value': value, 'confidence': confidence, 'evidence': evidence})